    &mut self,
    searcher: &Searcher,
    bytes: &[u8],
    range: std::ops::Range<usize>,
) -> io::Result<()> {
    self.replacer.clear();
    if self.standard.config.replacement.is_some() {
        let replacement = (*self.standard.config.replacement)
            .as_ref()
            .map(|r| &*r)
            .unwrap();
